11	// ToolSpec says how one scanner is invoked: from a binary or from an image run
12	// by the configured container engine, and which one.
13	//
14	// It replaces the `source ToolSource, image string` pair that every command
15	// builder used to take. That pair had nowhere to carry the configured binary
16	// path, which is why `scan.trivy_path` was declared, defaulted, tilde-expanded
17	// on load — and read by nothing (D27). Carrying all three together means a
18	// builder cannot see the source without also seeing what to run.
19	type ToolSpec struct {
20		Source ToolSource
21		// Binary is what to exec when Source is ToolSourceBinary: the configured
22		// path when there is one, else the plain name resolved on PATH.
23		Binary string
24		// Image is the OCI image when Source is ToolSourceContainer.
25		Image string
26		// HostSocket is the engine socket to bind-mount so a containerised Trivy
27		// can inspect an image the host holds. Empty means there is none to mount,
28		// which is rootless podman without `podman system service`; the builder
29		// then makes no mount rather than inventing a path (§3.67).
30		//
31		// Only the Trivy image path reads it. A directory scan mounts the
32		// directory and nothing else.
33		HostSocket string
34	}
35	
36	// TrivySpec, GitleaksSpec and PlumberSpec are how a resolved DependencyStatus
37	// is handed to the command builders.
38	func (d DependencyStatus) TrivySpec() ToolSpec {
39		return ToolSpec{
40			Source:     d.TrivySource,
41			Binary:     d.TrivyBinary,
42			Image:      d.TrivyImage,
43			HostSocket: d.ImageScanSocket,
44		}
45	}
46	
47	func (d DependencyStatus) GitleaksSpec() ToolSpec {
48		return ToolSpec{Source: d.GitleaksSource, Binary: d.GitleaksBinary, Image: d.GitleaksImage}
49	}
50	
51	func (d DependencyStatus) PlumberSpec() ToolSpec {
52		return ToolSpec{Source: d.PlumberSource, Binary: d.PlumberBinary, Image: d.PlumberImage}
53	}
54	
55	// toolResolution is what detection worked out for one scanner.
56	type toolResolution struct {
57		Available bool
58		Source    ToolSource
59		Binary    string
60		Version   string
61	}
62	
63	// resolveTool decides where one scanner runs from.
64	//
65	// The three preferences differ in exactly one way that matters: `binary` does
66	// **not** fall back to a container. That silent fallback is what kept D27 invisible
67	// — a configured path that was never read still produced working scans, run by
68	// something other than what was asked for. Asking for a binary and not having
69	// one is now an unavailable tool, which the dashboard reports.
70	func resolveTool(pref, configuredPath, name, image string, engineAvailable bool, versionArgs ...string) toolResolution {
71		useBinary := func() (toolResolution, bool) {
72			path, ok := locateBinary(configuredPath, name)
73			if !ok {
74				return toolResolution{Source: ToolSourceNone}, false
75			}
76			return toolResolution{
77				Available: true,
78				Source:    ToolSourceBinary,
79				Binary:    path,
80				Version:   toolVersion(path, versionArgs...),
81			}, true
82		}
83	
84		useImage := func() (toolResolution, bool) {
85			if !engineAvailable || !imageIsLocal(image) {
86				return toolResolution{Source: ToolSourceNone}, false
87			}
88			return toolResolution{
89				Available: true,
90				Source:    ToolSourceContainer,
91				Version:   containerToolVersion(image, versionArgs...),
92			}, true
93		}
94	
95		switch pref {
96		case config.ToolSourceBinary:
97			res, _ := useBinary()
98			return res
99		case config.ToolSourceImage:
100			res, _ := useImage()
101			return res
102		default: // config.ToolSourceAuto, and an empty value from a config that predates the setting
103			if res, ok := useBinary(); ok {
104				return res
105			}
106			res, _ := useImage()
107			return res
108		}
109	}
110	
111	// locateBinary returns the executable to run. A configured path is taken as
112	// given — it is the one thing the user stated explicitly — and only checked for
113	// existence; anything else is resolved on PATH.
114	func locateBinary(configuredPath, name string) (string, bool) {
115		if configuredPath != "" {
116			if info, err := os.Stat(configuredPath); err == nil && !info.IsDir() {
117				return configuredPath, true
118			}
119			// A path that was set and does not exist resolves to nothing rather than
120			// quietly falling through to PATH: the user named a file.
121			return "", false
122		}
123		path, err := exec.LookPath(name)
124		if err != nil || path == "" {
125			return "", false
126		}
127		return path, true
128	}
129	
130	// toolVersion asks the binary what it is. A tool that will not answer is still
131	// usable, so the version is best-effort.
132	func toolVersion(path string, args ...string) string {
133		out, err := exec.Command(path, args...).Output()
134		if err != nil {
135			return ""
136		}
137		return string(out)
138	}
139	
140	// containerToolVersion asks the image what it is, through the configured
141	// engine. The engine's name is part of the answer — it is what the dashboard
142	// shows to say where the tool is coming from.
143	func containerToolVersion(image string, args ...string) string {
144		name := engine.Current().Name
145		runArgs := append([]string{"run", "--rm", image}, args...)
146		out, err := exec.Command(engine.Current().Binary, runArgs...).Output() //nolint:gosec // the binary is a declared engine name or a configured path
147		if err != nil {
148			return name
149		}
150		return name + ":" + string(out)
151	}
