package config

import "slices"

// The scanners and the categories they serve, as the configuration names them.
//
// The table that says which tool serves which category, what each one needs and
// which are ticked by default lives in internal/scan (toolbox.go): it is the one
// source of truth. This file only declares the identifiers the YAML is written
// with, because the configuration cannot import the package that reads it —
// scan imports config, not the other way round. A test in scan checks that the
// two agree.

// Tool identifiers, as they appear under `scan.tools` and in a category's
// `tools` list.
const (
	ToolTrivy       = "trivy"
	ToolGitleaks    = "gitleaks"
	ToolPlumber     = "plumber"
	ToolKubeconform = "kubeconform"
	ToolHelm        = "helm"
	ToolKustomize   = "kustomize"
)

// ToolIDs lists every scanner, in the order the tables use.
func ToolIDs() []string {
	return []string{ToolTrivy, ToolGitleaks, ToolPlumber, ToolKubeconform, ToolHelm, ToolKustomize}
}

// Category identifiers, as they appear under `scan.categories`.
const (
	CategoryVuln      = "vuln"
	CategorySecret    = "secret"
	CategoryMisconfig = "misconfig"
	CategoryLicense   = "license"
	CategoryCI        = "ci"
)

// CategoryIDs lists every category, in the order the tables use.
func CategoryIDs() []string {
	return []string{CategoryVuln, CategorySecret, CategoryMisconfig, CategoryLicense, CategoryCI}
}

// ToolConfig is what every scanner is configured with: where it runs from, and
// what to run.
type ToolConfig struct {
	Source string `yaml:"source"`           // auto | binary | image
	Binary string `yaml:"binary"`           // custom executable; empty resolves the name on PATH
	Image  string `yaml:"image"`            // OCI image; empty is the tool's default
	Config string `yaml:"config,omitempty"` // rules file, for the tools that read one
}

// TrivyConfig adds what only Trivy has: the client-server mode and its two
// result filters.
type TrivyConfig struct {
	ToolConfig `yaml:",inline"`
	Server     TrivyServerConfig `yaml:"server"`
	// IgnoreUnfixed only shows vulnerabilities that have a fix.
	IgnoreUnfixed bool `yaml:"ignore_unfixed"`
	// IgnoreEOL drops end-of-life package vulnerabilities
	// (--ignore-status end_of_life).
	IgnoreEOL bool `yaml:"ignore_eol"`
}

// TrivyServerConfig is Trivy's client-server mode. The address is kept while
// the mode is off, so switching it back on does not lose what was typed — but a
// scan must not see it until Enabled says the mode is wanted.
type TrivyServerConfig struct {
	Enabled bool   `yaml:"enabled"`
	URL     string `yaml:"url"`
}

// GitleaksConfig adds whether git history is searched (omit --no-git).
type GitleaksConfig struct {
	ToolConfig `yaml:",inline"`
	History    bool `yaml:"history"`
}

// KubeconformConfig adds the release manifests are validated against, as
// kubeconform takes it: a full x.y.z, or "master". It decides whether an
// apiVersion counts as removed. Empty is DefaultKubernetesVersion.
type KubeconformConfig struct {
	ToolConfig        `yaml:",inline"`
	KubernetesVersion string `yaml:"kubernetes_version"`
}

// ScanTools is every scanner's settings, one block per tool.
type ScanTools struct {
	Trivy       TrivyConfig       `yaml:"trivy"`
	Gitleaks    GitleaksConfig    `yaml:"gitleaks"`
	Plumber     ToolConfig        `yaml:"plumber"`
	Kubeconform KubeconformConfig `yaml:"kubeconform"`
	Helm        ToolConfig        `yaml:"helm"`
	Kustomize   ToolConfig        `yaml:"kustomize"`
}

// Tool returns the settings every scanner shares, by identifier — what lets
// defaults, path expansion and detection loop over the tools instead of
// repeating a block per tool. Nil for an unknown identifier.
func (t *ScanTools) Tool(id string) *ToolConfig {
	switch id {
	case ToolTrivy:
		return &t.Trivy.ToolConfig
	case ToolGitleaks:
		return &t.Gitleaks.ToolConfig
	case ToolPlumber:
		return &t.Plumber
	case ToolKubeconform:
		return &t.Kubeconform.ToolConfig
	case ToolHelm:
		return &t.Helm
	case ToolKustomize:
		return &t.Kustomize
	}
	return nil
}

// CategoryConfig is one category: whether it runs, and which of its tools run
// it. A category that is off keeps its list, the way the Trivy server keeps its
// address while the mode is off.
type CategoryConfig struct {
	Enabled bool     `yaml:"enabled"`
	Tools   []string `yaml:"tools"`
}

// Has reports whether a tool is ticked in this category, whether or not the
// category itself is on.
func (c CategoryConfig) Has(tool string) bool {
	return slices.Contains(c.Tools, tool)
}

// With returns the category with a tool ticked or unticked. The list is always
// a new slice: a Config is copied by value between views, and an in-place edit
// would reach into every copy that shares the backing array.
func (c CategoryConfig) With(tool string, on bool) CategoryConfig {
	tools := slices.DeleteFunc(slices.Clone(c.Tools), func(t string) bool { return t == tool })
	if on {
		tools = append(tools, tool)
	}
	c.Tools = tools
	return c
}

// ScanCategories is what a scan looks for.
type ScanCategories struct {
	Vuln      CategoryConfig `yaml:"vuln"`
	Secret    CategoryConfig `yaml:"secret"`
	Misconfig CategoryConfig `yaml:"misconfig"`
	License   CategoryConfig `yaml:"license"`
	CI        CategoryConfig `yaml:"ci"`
}

// Category returns one category by identifier. Nil for an unknown identifier.
func (c *ScanCategories) Category(id string) *CategoryConfig {
	switch id {
	case CategoryVuln:
		return &c.Vuln
	case CategorySecret:
		return &c.Secret
	case CategoryMisconfig:
		return &c.Misconfig
	case CategoryLicense:
		return &c.License
	case CategoryCI:
		return &c.CI
	}
	return nil
}

// isZero is a `categories` block the file does not carry: nothing on and no
// list anywhere. A block that is present always has lists, since saving writes
// them, so an all-off one is still an answer.
func (c ScanCategories) isZero() bool {
	for _, id := range CategoryIDs() {
		cat := c.Category(id)
		if cat.Enabled || cat.Tools != nil {
			return false
		}
	}
	return true
}

// DefaultScanCategories is what a new context scans for: vulnerabilities and
// secrets, with each category's default tools ticked. The defaults must match
// the table in internal/scan, which a test there checks.
func DefaultScanCategories() ScanCategories {
	return ScanCategories{
		Vuln:      CategoryConfig{Enabled: true, Tools: []string{ToolTrivy}},
		Secret:    CategoryConfig{Enabled: true, Tools: []string{ToolTrivy, ToolGitleaks}},
		Misconfig: CategoryConfig{Tools: []string{ToolTrivy}},
		License:   CategoryConfig{Tools: []string{ToolTrivy}},
		CI:        CategoryConfig{Tools: []string{ToolPlumber}},
	}
}

package config

// legacyScanKeys are the flat `scan:` keys that `categories:` and `tools:`
// replaced. They are read at load, carried over by migrateScanSection, and
// cleared, so they leave the file on the next save — every tag is omitempty
// for that reason alone.
type legacyScanKeys struct {
	TrivySource       string `yaml:"trivy_source,omitempty"`
	TrivyPath         string `yaml:"trivy_path,omitempty"`
	TrivyImage        string `yaml:"trivy_image,omitempty"`
	UseTrivyServer    bool   `yaml:"use_trivy_server,omitempty"`
	TrivyServer       string `yaml:"trivy_server,omitempty"`
	IgnoreUnfixed     bool   `yaml:"ignore_unfixed,omitempty"`
	IgnoreEOL         bool   `yaml:"ignore_eol,omitempty"`
	GitleaksSource    string `yaml:"gitleaks_source,omitempty"`
	GitleaksPath      string `yaml:"gitleaks_path,omitempty"`
	GitleaksImage     string `yaml:"gitleaks_image,omitempty"`
	GitleaksConfig    string `yaml:"gitleaks_config,omitempty"`
	GitleaksHistory   bool   `yaml:"gitleaks_history,omitempty"`
	PlumberSource     string `yaml:"plumber_source,omitempty"`
	PlumberPath       string `yaml:"plumber_path,omitempty"`
	PlumberImage      string `yaml:"plumber_image,omitempty"`
	PlumberConfig     string `yaml:"plumber_config,omitempty"`
	KubeconformSource string `yaml:"kubeconform_source,omitempty"`
	KubeconformPath   string `yaml:"kubeconform_path,omitempty"`
	KubeconformImage  string `yaml:"kubeconform_image,omitempty"`
	KubernetesVersion string `yaml:"kubernetes_version,omitempty"`
	HelmSource        string `yaml:"helm_source,omitempty"`
	HelmPath          string `yaml:"helm_path,omitempty"`
	HelmImage         string `yaml:"helm_image,omitempty"`
	KustomizeSource   string `yaml:"kustomize_source,omitempty"`
	KustomizePath     string `yaml:"kustomize_path,omitempty"`
	KustomizeImage    string `yaml:"kustomize_image,omitempty"`

	EnableVuln      bool `yaml:"enable_vuln,omitempty"`
	EnableSecret    bool `yaml:"enable_secret,omitempty"`
	EnableMisconfig bool `yaml:"enable_misconfig,omitempty"`
	EnableLicense   bool `yaml:"enable_license,omitempty"`
	EnableCIScore   bool `yaml:"enable_ci_score,omitempty"`
	EnableK8sSchema bool `yaml:"enable_k8s_schema,omitempty"`
}

// migrateScanSection carries the flat `scan:` keys into `tools:` and
// `categories:`.
//
// migrateGitLabSection's shape: before the defaults, field by field, and only
// where the new value is empty, so a hand-edited file that carries both keeps
// what was written later. A bool can only be carried as "on": false is both
// "unset" and "off", so no guard could tell the two apart, and a legacy `true`
// is the only value that says anything.
//
// The categories are carried whole or not at all: a `categories:` block that is
// present is an answer, even with everything off, and mixing it with the old
// switches would make one category's state depend on which file wrote it.
func migrateScanSection(s *ScanConfig) {
	l := s.Legacy
	if l == (legacyScanKeys{}) {
		return
	}
	defer func() { s.Legacy = legacyScanKeys{} }()

	t := &s.Tools
	carryTool(&t.Trivy.ToolConfig, l.TrivySource, l.TrivyPath, l.TrivyImage, "")
	carryTool(&t.Gitleaks.ToolConfig, l.GitleaksSource, l.GitleaksPath, l.GitleaksImage, l.GitleaksConfig)
	carryTool(&t.Plumber, l.PlumberSource, l.PlumberPath, l.PlumberImage, l.PlumberConfig)
	carryTool(&t.Kubeconform.ToolConfig, l.KubeconformSource, l.KubeconformPath, l.KubeconformImage, "")
	carryTool(&t.Helm, l.HelmSource, l.HelmPath, l.HelmImage, "")
	carryTool(&t.Kustomize, l.KustomizeSource, l.KustomizePath, l.KustomizeImage, "")

	t.Trivy.Server.Enabled = t.Trivy.Server.Enabled || l.UseTrivyServer
	carry(&t.Trivy.Server.URL, l.TrivyServer)
	t.Trivy.IgnoreUnfixed = t.Trivy.IgnoreUnfixed || l.IgnoreUnfixed
	t.Trivy.IgnoreEOL = t.Trivy.IgnoreEOL || l.IgnoreEOL
	t.Gitleaks.History = t.Gitleaks.History || l.GitleaksHistory
	carry(&t.Kubeconform.KubernetesVersion, l.KubernetesVersion)

	if s.Categories.isZero() {
		s.Categories = legacyCategories(l)
	}
}

// carryTool fills one tool's shared settings from its legacy keys.
func carryTool(dst *ToolConfig, source, path, image, configPath string) {
	carry(&dst.Source, source)
	carry(&dst.Binary, path)
	carry(&dst.Image, image)
	carry(&dst.Config, configPath)
}

func carry(dst *string, legacy string) {
	if *dst == "" {
		*dst = legacy
	}
}

// legacyCategories translates the six `enable_*` switches.
//
// Misconfiguration absorbs two of them: `enable_misconfig` ticks Trivy,
// `enable_k8s_schema` ticks kubeconform and both renderers — which served
// already whenever they were installed, and now become required. That is the
// one behaviour this migration changes, on purpose: what is ticked is what the
// dashboard reports as missing.
//
// All six off is a file written before any of them existed, the historical
// "never configured" reading: it gets the defaults, as it always did.
func legacyCategories(l legacyScanKeys) ScanCategories {
	c := DefaultScanCategories()
	if !l.EnableVuln && !l.EnableSecret && !l.EnableMisconfig &&
		!l.EnableLicense && !l.EnableCIScore && !l.EnableK8sSchema {
		return c
	}
	c.Vuln.Enabled = l.EnableVuln
	c.Secret.Enabled = l.EnableSecret
	c.License.Enabled = l.EnableLicense
	c.CI.Enabled = l.EnableCIScore
	c.Misconfig.Enabled = l.EnableMisconfig || l.EnableK8sSchema
	if l.EnableK8sSchema {
		var tools []string
		if l.EnableMisconfig {
			tools = append(tools, ToolTrivy)
		}
		c.Misconfig.Tools = append(tools, ToolKubeconform, ToolHelm, ToolKustomize)
	}
	return c
}

